import { spawnSync } from "node:child_process";

const checks = [
  {
    label: "legacy repository slug",
    pattern: ["arcaea", "viewer"].join("-"),
    paths: ["."],
  },
  {
    label: "legacy product name",
    pattern: ["Arcaea", "Viewer"].join(" "),
    paths: ["."],
  },
  {
    label: "legacy design-token namespace",
    pattern: ["--", "av", "-"].join(""),
    paths: ["."],
  },
  {
    label: "legacy component class namespace",
    pattern: [".", "av", "-"].join(""),
    paths: ["."],
  },
  ...[
    "data-node-id",
    "Generated by",
    "AI-generated",
    "ChatGPT",
    "OpenAI",
    "Claude",
    "Copilot",
    "Figma MCP",
  ].map((pattern) => ({
    label: `assistant/export marker: ${pattern}`,
    pattern,
    paths: ["src", "index.html"],
  })),
];

const findings = [];

for (const { label, pattern, paths } of checks) {
  const result = spawnSync(
    "git",
    ["grep", "-nI", "-F", "-e", pattern, "--", ...paths],
    { encoding: "utf8" },
  );

  if (result.status === 0 && result.stdout.trim()) {
    findings.push(`${label} (${pattern}):\n${result.stdout.trim()}`);
    continue;
  }

  if (result.status !== 1) {
    throw new Error(
      `Repository search failed for ${label}: ${result.stderr.trim() || `exit ${result.status}`}`,
    );
  }
}

if (findings.length > 0) {
  console.error("Repository hygiene checks failed:\n");
  console.error(findings.join("\n\n"));
  process.exit(1);
}

console.log("Repository hygiene checks passed.");
